import os
import json
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
os.makedirs(UPLOAD_DIR, exist_ok=True)

# Configuration loaded from environment
REPORT_ENGINE = os.environ.get('REPORT_ENGINE', 'wkhtmltopdf')
ALLOWED_TEMPLATES = ['invoice', 'receipt', 'summary']

def load_template(template_name):
    """Load HTML template from disk"""
    path = os.path.join('/app/templates', f'{template_name}.html')
    if not os.path.exists(path):
        return None
    with open(path, 'r') as f:
        return f.read()

def render_report(template_html, data):
    """Render template with user data substitution"""
    rendered = template_html
    for key, value in data.items():
        placeholder = '{{' + key + '}}'
        rendered = rendered.replace(placeholder, str(value))
    return rendered

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from template and user data"""
    body = request.get_json()
    if not body:
        return jsonify({'error': 'invalid request body'}), 400

    template_name = body.get('template', '')
    if template_name not in ALLOWED_TEMPLATES:
        return jsonify({'error': 'invalid template'}), 400

    user_data = body.get('data', {})
    if not isinstance(user_data, dict):
        return jsonify({'error': 'data must be object'}), 400

    # Load and render template
    template_html = load_template(template_name)
    if not template_html:
        return jsonify({'error': 'template not found'}), 500

    rendered_html = render_report(template_html, user_data)

    # Write rendered HTML to temp file
    html_file = tempfile.NamedTemporaryFile(suffix='.html', dir=UPLOAD_DIR, delete=False)
    html_file.write(rendered_html.encode('utf-8'))
    html_file.close()

    # Generate PDF using configured engine
    output_pdf = html_file.name.replace('.html', '.pdf')

    # Build command - uses user-controllable 'options' field for page size etc.
    cmd_parts = [REPORT_ENGINE]

    user_options = body.get('options', {})
    if isinstance(user_options, dict):
        for opt_key, opt_val in user_options.items():
            # Only allow known option prefixes
            if opt_key in ('page-size', 'orientation', 'margin-top', 'margin-bottom', 'margin-left', 'margin-right', 'dpi'):
                cmd_parts.append(f'--{opt_key}')
                cmd_parts.append(str(opt_val))

    cmd_parts.append(html_file.name)
    cmd_parts.append(output_pdf)

    try:
        result = subprocess.run(cmd_parts, capture_output=True, timeout=30, shell=False)
        if result.returncode != 0:
            return jsonify({'error': 'pdf generation failed', 'detail': result.stderr.decode('utf-8', errors='replace')[:200]}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'timeout'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        os.unlink(html_file.name)

    return send_file(output_pdf, mimetype='application/pdf', as_attachment=True, download_name='report.pdf')

@app.route('/api/v2/reports/preview', methods=['POST'])
def preview_report():
    """Return rendered HTML preview (no PDF generation)"""
    body = request.get_json()
    if not body:
        return jsonify({'error': 'invalid request body'}), 400

    template_name = body.get('template', '')
    if template_name not in ALLOWED_TEMPLATES:
        return jsonify({'error': 'invalid template'}), 400

    user_data = body.get('data', {})
    if not isinstance(user_data, dict):
        return jsonify({'error': 'data must be object'}), 400

    template_html = load_template(template_name)
    if not template_html:
        return jsonify({'error': 'template not found'}), 500

    rendered_html = render_report(template_html, user_data)
    return rendered_html, 200, {'Content-Type': 'text/html'}

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
